const rows = $input.all().map(function(item) {
  return item.json;
});

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function number(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return num.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function money(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return "$" + num.toLocaleString("en-US", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  });
}

function percent(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return (num * 100).toFixed(1) + "%";
}

function pctPoint(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  const points = num * 100;
  return (points > 0 ? "+" : "") + points.toFixed(1) + " pts";
}

function formatCell(row, key) {
  if (key === "current_grs" || key === "prior_week_grs" || key === "prior_year_grs") return money(row[key]);
  if (key.includes("visits") || key.includes("converted") || key.includes("order_count") || key.includes("units")) return number(row[key]);
  if (key.includes("cvr") || key.includes("availability") || key.includes("oos") || key.includes("review") || key.includes("mrpi") || key.includes("wsi")) {
    if (key.includes("change")) return pctPoint(row[key]);
    return percent(row[key]);
  }
  return escapeHtml(row[key]);
}

function makeTable(title, tableRows, columns) {
  if (!Array.isArray(tableRows) || tableRows.length === 0) {
    return `<h2>${escapeHtml(title)}</h2><p><em>No rows returned.</em></p>`;
  }

  const headerHtml = columns.map(function(col) {
    return `<th>${escapeHtml(col.label)}</th>`;
  }).join("");

  const bodyHtml = tableRows.map(function(row) {
    const cells = columns.map(function(col) {
      const value = formatCell(row, col.key);
      const className = col.key === "diagnosis" ? "diagnosis" : "";
      return `<td class="${className}">${value}</td>`;
    }).join("");

    return `<tr>${cells}</tr>`;
  }).join("");

  return `
    <h2>${escapeHtml(title)}</h2>
    <table>
      <thead><tr>${headerHtml}</tr></thead>
      <tbody>${bodyHtml}</tbody>
    </table>
  `;
}

const summaryColumns = [
