  { label: "SKU", key: "sku" },
  { label: "Requested Issue", key: "requested_issue" },
  { label: "Status", key: "prstatusname" },
  { label: "Status Reason", key: "skustatusreasonname" },
  { label: "Supplier Match", key: "supplier_match_status" },
  { label: "Diagnosis", key: "diagnosis" },
  { label: "Recommended Next Step", key: "recommended_next_step" }
];

const performanceColumns = [
